-- ROUND ROBIN TABLE

CREATE table round_table
(
    Id INT,
    Name varchar(4000),
    Salary INT
)
WITH
(
    DISTRIBUTION = ROUND_ROBIN
);

SELECT * FROM round_table;

--REPLICATE TABLE

CREATE SCHEMA gold;

create table gold.dim_product
(
    dim_key_product INT,
    product_id INT,
    product_name varchar(4000)
)
WITH
(
    DISTRIBUTION = REPLICATE
);

--HASH TABLE

CREATE TABLE gold.fact_table
(
    dim_key_product INT,
    Revenue INT,
    Cost INT
)
WITH
(
    DISTRIBUTION = HASH(dim_key_product)
);

CREATE DATABASE SCOPED CREDENTIAL SynapseCreds_dedicated
WITH
    IDENTITY = 'Managed Identity';

-- EXTERNAL DATA SOURCE

CREATE EXTERNAL DATA SOURCE raw_ext_source_dedicated
WITH
(
    LOCATION = 'https://sasynapsedemo.dfs.core.windows.net/raw',
    CREDENTIAL = SynapseCreds_dedicated
);

CREATE EXTERNAL DATA SOURCE enriched_ext_source_dedicated
WITH
(
    LOCATION = 'https://sasynapsedemo.dfs.core.windows.net/enriched',
    CREDENTIAL = SynapseCreds_dedicated
);

CREATE EXTERNAL DATA SOURCE enriched_ext_source_dedicated_acfss
WITH
(
    LOCATION = 'abfss://enriched@sasynapsedemo.dfs.core.windows.net/',
    CREDENTIAL = SynapseCreds_dedicated
);

--DROP EXTERNAL FILE FORMAT PARQUET_FORMAT;
CREATE EXTERNAL FILE FORMAT PARQUET_FORMAT_DEDICATED
WITH
(
    FORMAT_TYPE = PARQUET,
    DATA_COMPRESSION = 'org.apache.hadoop.io.compress.SnappyCodec'
);
